package pilot

import java.io.IOException
import java.util.concurrent.atomic.AtomicInteger
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertThrows
import org.junit.jupiter.api.Test

// Temporary reproduction for review; not part of the deliverable.
class ReviewReproTest {
    // Gateway that atomically dedups by idempotency key and debits a balance.
    // lostResponses: how many first calls lose the response AFTER the debit.
    private class FakeGateway(var balance: Long, private var lostResponses: Int) : PaymentGateway {
        val receiptsByKey = mutableMapOf<String, Receipt>()
        val keys = mutableListOf<String>()
        var debits = 0
        @Synchronized
        override fun charge(request: Charge, idempotencyKey: String): Receipt {
            keys += idempotencyKey
            val receipt = receiptsByKey[idempotencyKey] ?: run {
                if (balance < request.cents) throw RejectedCharge()
                balance -= request.cents
                debits++
                Receipt("r$debits").also { receiptsByKey[idempotencyKey] = it }
            }
            if (lostResponses > 0) { lostResponses--; throw IOException("response lost after debit") }
            return receipt
        }
    }

    private fun keys(): () -> String { val n = AtomicInteger(); return { "k" + n.incrementAndGet() } }

    @Test fun `lost response after debit - one call must debit once`() {
        val gw = FakeGateway(balance = 1_000, lostResponses = 1)
        val receipt = PaymentService(gw, keys()).charge(Charge("acc", 100))
        println("keys=${gw.keys} debits=${gw.debits} balance=${gw.balance} receipt=$receipt")
        assertEquals(1, gw.debits, "keys sent: ${gw.keys}")
    }

    @Test fun `two lost responses - one call must debit once`() {
        val gw = FakeGateway(balance = 1_000, lostResponses = 2)
        PaymentService(gw, keys()).charge(Charge("acc", 100))
        println("keys=${gw.keys} debits=${gw.debits} balance=${gw.balance}")
        assertEquals(1, gw.debits, "keys sent: ${gw.keys}")
    }

    @Test fun `lost response then retry rejected although money was taken`() {
        val gw = FakeGateway(balance = 100, lostResponses = 1)
        val result = runCatching { PaymentService(gw, keys()).charge(Charge("acc", 100)) }
        println("result=$result keys=${gw.keys} debits=${gw.debits} balance=${gw.balance}")
        assertEquals(Receipt("r1"), result.getOrNull(), "debited=${gw.debits}, caller got: $result")
    }

    @Test fun `rejected charge is not retried`() {
        var calls = 0
        val svc = PaymentService({ _, _ -> calls++; throw RejectedCharge() }, keys())
        assertThrows(RejectedCharge::class.java) { svc.charge(Charge("acc", 100)) }
        assertEquals(1, calls)
    }

    @Test fun `io exception retried up to three attempts then rethrown`() {
        var calls = 0
        val svc = PaymentService({ _, _ -> calls++; throw IOException("down") }, keys())
        assertThrows(IOException::class.java) { svc.charge(Charge("acc", 100)) }
        assertEquals(3, calls)
    }

    @Test fun `separate calls with same data are separate payments`() {
        val gw = FakeGateway(balance = 1_000, lostResponses = 0)
        val svc = PaymentService(gw, keys())
        svc.charge(Charge("acc", 100)); svc.charge(Charge("acc", 100))
        assertEquals(2, gw.debits)
    }
}

